SELECT a.*
FROM airports AS a
WHERE NOT EXISTS (
    SELECT 1 FROM flights AS f WHERE f.SourceAirport = a.AirportCode
)
AND NOT EXISTS (
    SELECT 1 FROM flights AS f WHERE f.DestAirport = a.AirportCode
);

SELECT a."Airline"
FROM "airlines" AS a
WHERE EXISTS (
    SELECT 1 FROM "flights" AS f
    WHERE f."Airline" = a."uid" AND f."SourceAirport" = 'CVO'
)
AND NOT EXISTS (
    SELECT 1 FROM "flights" AS f
    WHERE f."Airline" = a."uid" AND f."SourceAirport" = 'APG'
);

SELECT Nationality, COUNT(*) AS people_count
FROM people
GROUP BY Nationality;

SELECT Nationality, COUNT(*) AS people_count
FROM people
GROUP BY Nationality;

SELECT Year, AVG(Weight) AS average_weight, AVG(Year) AS average_year
FROM cars_data
GROUP BY Year;

SELECT StuID, COUNT(*) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT StuID, COUNT(*) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT country_code, COUNT(*) AS player_count
FROM players
GROUP BY country_code;

SELECT "Citizenship", COUNT(*) AS singer_count
FROM "singer"
GROUP BY "Citizenship";

SELECT "Citizenship", COUNT(*) AS "Singer_Count"
FROM "singer"
GROUP BY "Citizenship";

SELECT "Location", COUNT(*) AS shop_count
FROM "shop"
GROUP BY "Location";

SELECT DISTINCT o.state
FROM Owners AS o
JOIN Professionals AS p ON p.state = o.state;

SELECT SUM(Population) AS total_population, AVG(SurfaceArea) AS average_surface_area
FROM country
WHERE Continent = 'North America' AND SurfaceArea > 3000;

SELECT Name, Population, AVG(Population) OVER () AS AveragePopulation
FROM country
WHERE Continent = 'North America' AND SurfaceArea > 3000;

